def request_booking(request, store, notifier, clock):
    checked = validate(request)
    if not checked.ok:
        return Rejected(checked.reason)
    existing = store.bookings_in(request.room)
    outcome = decide(checked.minutes, overlaps(existing, checked))
    if outcome != "Confirmed":
        return Rejected(outcome)
    booking = store.save(checked, made_at=clock.now())
    notifier.send(booking.id, request.user)
    return Confirmed(booking.id)

